                                                                                                                                                                                                               
  CREATE TABLE "JW_APP_TAG"                                                                                                                                                                     
   (	"APP_TAG_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 22 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NVARCHAR2(256),                                                                                                                                                                                  
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                         
	"UPDATED_BY" NVARCHAR2(256),                                                                                                                                                                                  
	"UPDATE_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                           
	"TENANT_ID" NUMBER(20,0) DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                           
	"REMARK" VARCHAR2(200),                                                                                                                                                                                       
	"TAG_NAME" VARCHAR2(200) NOT NULL ENABLE,                                                                                                                                                                     
	"SORT_NUM" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                                  
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                             
	 PRIMARY KEY ("APP_TAG_ID")                                                                                                                                                                                   
  USING INDEX  ENABLE,                                                                                                                                                                                         
	 CHECK (SORT_NUM >= 0) ENABLE                                                                                                                                                                                 
   ) ;                                                                                                                                                                                                         

